head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70019";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — formKey, keyValue, returnKey

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70019.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_formKey", fn: function () { return String(String((dma_pageContext.get("formKey") ?? ""))); } },
        { childId: "ipt_keyValue", fn: function () { return String(String((dma_pageContext.get("keyValue") ?? ""))); } },
        { childId: "ipt_returnKey", fn: function () { return String(String((dma_pageContext.get("returnKey") ?? ""))); } },
        { childId: "ipt_searchWord", fn: function () { return String(String((dma_pageContext.get("searchWord") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_goSearchSW();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_12_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_12_onclick = async function(e){
    try {
        await scwin.goSearchSW()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70019.input_12_onclick' }); }
};

/**
 * @method
 * @name grd_resultVo_oncellclick
 * @description grd_resultVo 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultVo_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultVo');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultVo */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.setCorpInfo(r["issueCode"], r["isuKorAbbrv"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultVo.oncellclick' });
    }
};

/**
 * @method
 * @name __on_enter_1_ipt_searchword
 * @description on enter 1 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.goSearchSW() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70019.__on_enter_1_ipt_searchWord' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goSearchSW
 * @description go Search SW 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearchSW = async function () {
    const sbmOptions = {
        id: "tx_goSearchSW",
        method: "post",
        action: "/discls/disclosureCommon.do",
        ref: "dma_goSearchSWReq",
        target: "dlt_resultVo=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goSearchSW
 * @description go Search SW 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearchSW = async function () {
    const swObj = (document.swForm || { elements: [] });
    swObj.action = "/discls/disclosureCommon.do";
    $c.util.getComponent('dma_goSearchSWReq').set('method', "searchCommonPop");
    $c.util.getComponent('dma_goSearchSWReq').set('searchYn', "Y");
    await scwin.tx_goSearchSW();
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {*} comAbbrv comAbbrv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (repIsuSrtCd, comAbbrv) {
    let str = "";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    const returnKey = $c.util.getComponent('ipt_returnKey').getValue();
    try {
        const code = (repIsuSrtCd == null || repIsuSrtCd === "") ? "-" : repIsuSrtCd;
        const name = (comAbbrv == null || comAbbrv === "") ? "-" : comAbbrv;
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setSelectedData === 'function' ? (scwin.openerScwin()).fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name) : void 0), $c.win.closePopup([(String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldods70019' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

/**
 * @method
 * @name setCorpInfo2
 * @description set Corp Info2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo2 = async function () {
    const returnKey = $c.util.getComponent('ipt_returnKey').getValue();
    try {
        const code = '-';
        const name = '-';
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setSelectedData === 'function' ? (scwin.openerScwin()).fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name) : void 0), $c.win.closePopup([(String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldods70019' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
